{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "Beginning with the 2026–2027 school year, the bill would require local education agencies (LEAs) to classify school nurses they employ as licensed personnel and pay them under the LEA’s salary schedule for licensed personnel.",
      "rationale": "Conveys the LEA's classification and salary-schedule duties for its employed school nurses."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "An LEA could still contract with the Tennessee public school nurse program for school health services and set the contract’s terms, including nurse compensation; the employee-pay requirements would not apply to LEA contractors.",
      "rationale": "Covers preserved contracting authority, discretion over contract terms and compensation, and the contractor compensation exclusion."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "An employed school nurse who is a licensed registered nurse, holds National Board for Certification of School Nurses certification, and has no experience would have to receive the same base salary as a licensed teacher with a bachelor’s degree and no experience.",
      "rationale": "Conveys the employment, licensing, certification, and experience conditions and the matching teacher base-salary benchmark."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Nurses with more training and experience than those benchmarks would have to receive more than that base salary",
      "rationale": "Conveys mandatory pay above the base salary for employed nurses exceeding the stated training and experience benchmarks."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "Nurses with more training and experience than those benchmarks would have to receive more than that base salary, and nurses with less would have to receive less.",
      "rationale": "Conveys mandatory pay below the base salary for employed nurses with less training and experience than the stated benchmarks."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Adopting a salary schedule under the cited provision could not reduce the salary of a school nurse already employed by the LEA.",
      "rationale": "Covers the prohibition on salary reductions for nurses employed by the LEA when the schedule is adopted."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The bill would take effect July 1, 2026, and apply to that school year and each school year after.",
      "rationale": "States the effective date and continuing application; the opening sentence identifies the applicable school year as 2026–2027."
    }
  ]
}
